examples.template:
Column(
    modifier = Modifier
        .widthIn(max = {{maxWidth}}.dp)
        .heightIn(max = {{maxHeight}}.dp)
        .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.lg)
        .semantics { contentDescription = {{label}} }
        .verticalScroll(rememberScrollState())
        .padding(MonarchTheme.spacing.space3),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    repeat({{events.count}}) { index ->
        MonarchText(text = "{{events.prefix|raw}}${index + 1}{{events.suffix|raw}}")
    }
}

examples.code:
Column(
    modifier = Modifier
        .widthIn(max = 420.dp)
        .heightIn(max = 220.dp)
        .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.lg)
        .semantics { contentDescription = "Recent events" }
        .verticalScroll(rememberScrollState())
        .padding(MonarchTheme.spacing.space3),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    repeat(20) { index ->
        MonarchText(text = "Event ${index + 1}: status changed")
    }
}

Row(
    modifier = Modifier.horizontalScroll(rememberScrollState()),
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
) {
    repeat(8) { index ->
        MonarchCard { MonarchText(text = "Report ${index + 1}") }
    }
}
